function formatProgressBar(iteration, total, prefix = '', suffix = '', decimals = 1, length = 100, fill = '█', printEnd = '\r') {
    const percent = (iteration / total).toFixed(decimals);
    const filledLength = Math.floor(length * iteration / total);
    const bar = fill.repeat(filledLength) + '-'.repeat(length - filledLength);
    return `${prefix} |${bar}| ${percent}% ${suffix}${printEnd}`;
}

// 標準入力から引数を読み取る
const readline = require('readline');
const rl = readline.createInterface({
    input: process.stdin,
    output: process.stdout,
    terminal: false
});

let lines = [];
rl.on('line', (line) => {
    lines.push(line);
});

rl.on('close', () => {
    // 引数を順にパース
    const iteration = parseInt(lines[0]);
    const total = parseInt(lines[1]);
    const prefix = lines[2] || '';
    const suffix = lines[3] || '';
    const decimals = lines[4] ? parseInt(lines[4]) : 1;
    const length = lines[5] ? parseInt(lines[5]) : 100;
    const fill = lines[6] || '█';
    const printEnd = lines[7] || '\r';

    const result = formatProgressBar(iteration, total, prefix, suffix, decimals, length, fill, printEnd);
    // 標準出力に出力（printEndはそのまま含める）
    process.stdout.write(result);
});
```

