```javascript
function unwrapModel(input) {
    // 入力が空文字なら空文字を返す
    if (input === '') return '';

    // ラッパーのパターンを定義（DataParallel, DistributedDataParallel, DeepSpeed, FSDP）
    const wrappers = [
        /^nn\.DataParallel\((.*)\)$/,
        /^nn\.DistributedDataParallel\((.*)\)$/,
        /^deepspeed\.DeepSpeedEngine\((.*)\)$/,
        /^fsdp\.FullyShardedDataParallel\((.*)\)$/
    ];

    let current = input;
    let changed = true;

    // 再帰的にラッパーを外す
    while (changed) {
        changed = false;
        for (const pattern of wrappers) {
            const match = current.match(pattern);
            if (match) {
                current = match[1];
                changed = true;
                break;
            }
        }
    }

    return current;
}

// 標準入力から読み込み
const readline = require('readline');
const rl = readline.createInterface({
    input: process.stdin,
    output: process.stdout
});

let lines = [];
rl.on('line', (line) => {
    lines.push(line);
});

rl.on('close', () => {
    // 入力は1行のみ（関数の引数）
    const input = lines[0] || '';
    const result = unwrapModel(input);
    console.log(result);
});
```

