const fs = require('fs');

function parseInput() {
    const lines = require('fs').readFileSync('/dev/stdin', 'utf8').trim().split('\n');
    let idx = 0;
    function parseValue() {
        if (idx >= lines.length) return null;
        const line = lines[idx++];
        if (line === '') return null;
        if (line === 'true') return true;
        if (line === 'false') return false;
        if (line === 'None') return null;
        // リストの場合
        if (/^-?\d+$/.test(line)) {
            const n = parseInt(line);
            if (n >= 0 && idx < lines.length) {
                const arrLine = lines[idx++];
                if (arrLine !== '') {
                    const parts = arrLine.split(' ');
                    const arr = [];
                    for (let p of parts) {
                        if (p === 'True') arr.push(true);
                        else if (p === 'False') arr.push(false);
                        else if (p === 'None') arr.push(null);
                        else if (p.startsWith("'") && p.endsWith("'")) arr.push(p.slice(1, -1));
                        else if (!isNaN(Number(p))) arr.push(Number(p));
                        else arr.push(p);
                    }
                    return arr;
                }
            }
        }
        // 文字列（クォート付き）
        if (line.startsWith("'") && line.endsWith("'")) return line.slice(1, -1);
        // 数値
        if (!isNaN(Number(line))) return Number(line);
        return line;
    }
    return parseValue;
}

function openFile(fh, mode = 'r', needs_filename = false) {
    let fileHandle, filename;
    if (Array.isArray(fh)) {
        [fileHandle, filename] = fh;
    } else {
        fileHandle = fh;
        filename = fh;
    }
    // ファイルを開く（モードに応じて）
    let fd;
    if (mode.includes('r')) {
        fd = fs.openSync(fileHandle, 'r');
    } else if (mode.includes('w')) {
        fd = fs.openSync(fileHandle, 'w');
    } else if (mode.includes('a')) {
        fd = fs.openSync(fileHandle, 'a');
    } else {
        fd = fs.openSync(fileHandle, 'r');
    }
    // ファイルハンドルをラップ（簡易的に数値で返す）
    if (needs_filename) {
        return [fd, filename];
    } else {
        return fd;
    }
}

// メイン処理
const parser = parseInput();
const fh = parser();
const mode = parser() || 'r';
const needs_filename = parser() || false;

const result = openFile(fh, mode, needs_filename);

// 出力
if (Array.isArray(result)) {
    console.log(result.length);
    console.log(result.map(v => {
        if (typeof v === 'number') return v;
        if (typeof v === 'boolean') return v ? 'True' : 'False';
        if (v === null) return 'None';
        return `'${v}'`;
    }).join(' '));
} else {
    console.log(result);
}
```

