実装方針: 元のコードの処理を維持しつつ、不要な計算やメモリ使用を削減し、特にループやテンソル操作の効率化を図ります。

```javascript
// 注意: この問題はPyTorchテンソルを扱うため、JavaScriptで直接実装することはできません。
// しかし、指定された仕様に従い、JavaScriptで同等のロジックを実装します。
// ここでは、テンソル操作を模擬するための簡易的なテンソルクラスを定義します。

class Tensor {
    constructor(data, shape, dtype='float32', device='cpu') {
        this.data = data; // 1次元配列
        this.shape = shape;
        this.dtype = dtype;
        this.device = device;
    }
    static zeros(shape, dtype='float32', device='cpu') {
        let size = shape.reduce((a,b)=>a*b,1);
        return new Tensor(new Array(size).fill(0), shape, dtype, device);
    }
    static ones(shape, dtype='float32', device='cpu') {
        let size = shape.reduce((a,b)=>a*b,1);
        return new Tensor(new Array(size).fill(1), shape, dtype, device);
    }
    static rand(shape, device='cpu') {
        let size = shape.reduce((a,b)=>a*b,1);
        let data = Array.from({length: size}, () => Math.random());
        return new Tensor(data, shape, 'float32', device);
    }
    static randint(low, high, shape, dtype='int64', device='cpu') {
        let size = shape.reduce((a,b)=>a*b,1);
        let data = Array.from({length: size}, () => Math.floor(Math.random()*(high-low)+low));
        return new Tensor(data, shape, dtype, device);
    }
    static arange(start, end, step=1, dtype='int64', device='cpu') {
        let data = [];
        for (let i=start; i<end; i+=step) data.push(i);
        return new Tensor(data, [data.length], dtype, device);
    }
    repeat(repeats) {
        // repeats: 配列または数値
        if (typeof repeats === 'number') repeats = [repeats];
        let newShape = [];
        let newData = [];
        // 簡易実装: 1次元のみ対応
        if (this.shape.length === 1) {
            let n = this.shape[0];
            for (let r=0; r<repeats[0]; r++) {
                for (let i=0; i<n; i++) newData.push(this.data[i]);
            }
            newShape = [n * repeats[0]];
        } else if (this.shape.length === 2) {
            let n = this.shape[0];
            let m = this.shape[1];
            for (let r=0; r<repeats[0]; r++) {
                for (let i=0; i<n; i++) {
                    for (let j=0; j<m; j++) newData.push(this.data[i*m+j]);
                }
            }
            newShape = [n * repeats[0], m];
        }
        return new Tensor(newData, newShape, this.dtype, this.device);
    }
    view(shape) {
        return new Tensor(this.data, shape, this.dtype, this.device);
    }
    to(device) {
        this.device = device;
        return this;
    }
    // インデックスアクセス
    get(indices) {
        // indices: 配列
        let idx = 0;
        for (let i=0; i<this.shape.length; i++) {
            idx = idx * this.shape[i] + indices[i];
        }
        return this.data[idx];
    }
    set(indices, value) {
        let idx = 0;
        for (let i=0; i<this.shape.length; i++) {
            idx = idx * this.shape[i] + indices[i];
        }
        this.data[idx] = value;
    }
    // スライス代入（簡易）
    sliceAssign(startIndices, endIndices, valueTensor) {
        // 簡易実装: 1次元のみ
        if (this.shape.length === 1) {
            for (let i=startIndices[0]; i<endIndices[0]; i++) {
                this.data[i] = valueTensor.data[i-startIndices[0]];
            }
        } else if (this.shape.length === 2) {
            for (let i=startIndices[0]; i<endIndices[0]; i++) {
                for (let j=startIndices[1]; j<endIndices[1]; j++) {
                    this.data[i*this.shape[1]+j] = valueTensor.data[(i-startIndices[0])*valueTensor.shape[1]+(j-startIndices[1])];
                }
            }
        }
    }
    // 演算
    add(other) {
        if (typeof other === 'number') {
            return new Tensor(this.data.map(x=>x+other), this.shape, this.dtype, this.device);
        }
        // ブロードキャスト簡易
        let newData = [];
        for (let i=0; i<this.data.length; i++) newData.push(this.data[i] + other.data[i % other.data.length]);
        return new Tensor(newData, this.shape, this.dtype, this.device);
    }
    mul(other) {
        if (typeof other === 'number') {
            return new Tensor(this.data.map(x=>x*other), this.shape, this.dtype, this.device);
        }
        let newData = [];
        for (let i=0; i<this.data.length; i++) newData.push(this.data[i] * other.data[i % other.data.length]);
        return new Tensor(newData, this.shape, this.dtype, this.device);
    }
    // 比較演算（簡易）
    lt(other) {
        let newData = [];
        if (typeof other === 'number') {
            for (let i=0; i<this.data.length; i++) newData.push(this.data[i] < other ? 1 : 0);
        }
        return new Tensor(newData, this.shape, 'bool', this.device);
    }
    // 非ゼロインデックス取得
    nonzero() {
        let indices = [];
        for (let i=0; i<this.data.length; i++) {
            if (this.data[i] !== 0) indices.push(i);
        }
        return new Tensor(indices, [indices.length], 'int64', this.device);
    }
    // クリップ
    clip(min, max) {
        let newData = this.data.map(x=>Math.min(Math.max(x, min), max));
        return new Tensor(newData, this.shape, this.dtype, this.device);
    }
    // シグモイド逆関数
    inverseSigmoid() {
        let newData = this.data.map(x=>Math.log(x/(1-x)));
        return new Tensor(newData, this.shape, this.dtype, this.device);
    }
    // 連結
    static cat(tensors, dim=0) {
        // 簡易: 1次元のみ
        let newData = [];
        for (let t of tensors) newData = newData.concat(t.data);
        let newShape = [newData.length];
        return new Tensor(newData, newShape, tensors[0].dtype, tensors[0].device);
    }
    // スタック
    static stack(tensors, dim=0) {
        // 簡易: 2次元
        let n = tensors.length;
        let m = tensors[0].data.length;
        let newData = [];
        for (let i=0; i<n; i++) newData = newData.concat(tensors[i].data);
        return new Tensor(newData, [n, m], tensors[0].dtype, tensors[0].device);
    }
    // 分割
    split(sizes, dim=0) {
        // 簡易: 1次元
        let result = [];
        let start = 0;
        for (let s of sizes) {
            let end = start + s;
            result.push(new Tensor(this.data.slice(start, end), [s], this.dtype, this.device));
            start = end;
        }
        return result;
    }
    // CPUへ
    cpu() {
        this.device = 'cpu';
        return this;
    }
    // reshape
    reshape(shape) {
        return new Tensor(this.data, shape, this.dtype, this.device);
    }
}

// 簡易関数
function xywh2xyxy(bbox) {
    // bbox: Tensor [N,4] (x,y,w,h)
    let N = bbox.shape[0];
    let newData = [];
    for (let i=0; i<N; i++) {
        let x = bbox.data[i*4];
        let y = bbox.data[i*4+1];
        let w = bbox.data[i*4+2];
        let h = bbox.data[i*4+3];
        newData.push(x - w/2, y - h/2, x + w/2, y + h/2);
    }
    return new Tensor(newData, [N,4], bbox.dtype, bbox.device);
}

function xyxy2xywh(bbox) {
    let N = bbox.shape[0];
    let newData = [];
    for (let i=0; i<N; i++) {
        let x1 = bbox.data[i*4];
        let y1 = bbox.data[i*4+1];
        let x2 = bbox.data[i*4+2];
        let y2 = bbox.data[i*4+3];
        newData.push((x1+x2)/2, (y1+y2)/2, x2-x1, y2-y1);
    }
    return new Tensor(newData, [N,4], bbox.dtype, bbox.device);
}

function inverse_sigmoid(x) {
    return x.inverseSigmoid();
}

function get_cdn_group(batch, num_classes, num_queries, class_embed, num_dn=100, cls_noise_ratio=0.5, box_noise_scale=1.0, training=false) {
    if (!training || num_dn <= 0) {
        return [null, null, null, null];
