入力されたキー、デフォルト値、型変換関数を順に読み取り、辞書から値を取得し、型変換が失敗した場合はデフォルト値を返す関数を実装します。

```typescript
// 入力読み取り
const readline = require('readline');
const rl = readline.createInterface({
    input: process.stdin,
    output: process.stdout
});

let lines: string[] = [];
rl.on('line', (line) => {
    lines.push(line);
});

rl.on('close', () => {
    // パース: 最初の行は辞書の要素数
    const dictSize = parseInt(lines[0]);
    const dict: { [key: string]: string } = {};
    // 2行目は辞書のキーと値のペア（空白区切りで交互）
    const dictParts = lines[1].split(' ');
    for (let i = 0; i < dictSize; i++) {
        dict[dictParts[i * 2]] = dictParts[i * 2 + 1];
    }
    // 3行目はキー
    const key = lines[2];
    // 4行目はデフォルト値（空文字ならnull）
    const defaultStr = lines[3] || '';
    // 5行目は型変換関数（"int" など、なければ空文字）
    const typeStr = lines[4] || '';

    // デフォルト値の変換（空文字はnullとして扱う）
    let defaultValue: any = defaultStr === '' ? null : defaultStr;

    // 型変換関数の定義
    let typeFunc: ((val: string) => any) | null = null;
    if (typeStr === 'int') {
        typeFunc = (val: string) => parseInt(val);
    } else if (typeStr === 'float') {
        typeFunc = (val: string) => parseFloat(val);
    } else if (typeStr === 'bool') {
        typeFunc = (val: string) => val === 'true';
    } else if (typeStr === 'str') {
        typeFunc = (val: string) => val;
    } else if (typeStr !== '') {
        // 未知の型はエラー扱い（デフォルトを返す）
        typeFunc = null;
    }

    // 辞書から値を取得
    let result: any;
    if (key in dict) {
        const rawValue = dict[key];
        if (typeFunc) {
            try {
                result = typeFunc(rawValue);
            } catch (e) {
                result = defaultValue;
            }
        } else {
            result = rawValue;
        }
    } else {
        result = defaultValue;
    }

    // 出力形式に変換
    let output: string;
    if (result === null) {
        output = '';
    } else if (typeof result === 'boolean') {
        output = result ? 'true' : 'false';
    } else if (typeof result === 'number') {
        output = result.toString();
    } else if (typeof result === 'string') {
        output = result;
    } else {
        output = String(result);
    }

    console.log(output);
});
