```typescript
function _map_single_label(label_name: string): string {
    const entityMappings: Record<string, [string, string]> = {
        'nam_liv': ['B-PER', 'I-PER'],
        'nam_loc': ['B-LOC', 'I-LOC'],
        'nam_org': ['B-ORG', 'I-ORG']
    };

    if (label_name === 'O') {
        return 'O';
    }

    // 前方一致でB-またはI-を確認
    const prefix = label_name.startsWith('B-') ? 'B' : label_name.startsWith('I-') ? 'I' : null;
    if (prefix === null) {
        return 'O';
    }

    // キーを直接検索（部分一致を避けるため、完全一致または前方一致で確認）
    for (const [keyword, [bLabel, iLabel]] of Object.entries(entityMappings)) {
        if (label_name.includes(keyword)) {
            return prefix === 'B' ? bLabel : iLabel;
        }
    }

    // 既知のエンティティでない場合
    return prefix === 'B' ? 'B-MISC' : 'I-MISC';
}

