```typescript
type ViewDict = {
    text?: string;
    resource_id?: string;
    content_description?: string;
    class?: string;
    bounds: [[number, number], [number, number]];
};

type Selector = {
    text_re: string | null;
    resource_id_re: string | null;
    content_desc_re: string | null;
    class_re: string | null;
    in_coordinates: [number, number][];
    out_coordinates: [number, number][];
};

function safe_re_match(pattern: string, text: string): boolean {
    try {
        const regex = new RegExp(pattern);
        return regex.test(text);
    } catch {
        return false;
    }
}

function match(selector: Selector, view_dict: ViewDict): boolean {
    // 必須キーの存在チェック
    if (!('text' in view_dict) || !('resource_id' in view_dict) || !('class' in view_dict) || !('bounds' in view_dict)) {
        return false;
    }

    // 各正規表現チェック
    if (selector.text_re && !safe_re_match(selector.text_re, view_dict.text || '')) {
        return false;
    }
    if (selector.resource_id_re && !safe_re_match(selector.resource_id_re, view_dict.resource_id || '')) {
        return false;
    }
    if (selector.content_desc_re && !safe_re_match(selector.content_desc_re, view_dict.content_description || '')) {
        return false;
    }
    if (selector.class_re && !safe_re_match(selector.class_re, view_dict.class || '')) {
        return false;
    }

    // boundsの座標取得（バグ修正: bound_x_maxはbounds[0][0]ではなくbounds[1][0]）
    const bounds = view_dict.bounds;
    const bound_x_min = bounds[0][0];
    const bound_x_max = bounds[1][0];
    const bound_y_min = bounds[0][1];
    const bound_y_max = bounds[1][1];

    // in_coordinatesのチェック
    for (const [x, y] of selector.in_coordinates) {
        if (x < bound_x_min || x > bound_x_max || y < bound_y_min || y > bound_y_max) {
            return false;
        }
    }

    // out_coordinatesのチェック
    for (const [x, y] of selector.out_coordinates) {
        if (bound_x_min < x && x < bound_x_max && bound_y_min < y && y < bound_y_max) {
            return false;
        }
    }

    return true;
}

// 標準入力のパース
function parseInput(): { selector: Selector; view_dict: ViewDict } {
    const lines: string[] = [];
    const readline = require('readline');
    const rl = readline.createInterface({ input: process.stdin });

    return new Promise((resolve) => {
        rl.on('line', (line) => {
            lines.push(line);
