            resolve({
                selector: {
                    text_re: lines[0] || null,
                    resource_id_re: null,
                    content_desc_re: null,
                    class_re: null,
                    in_coordinates: [],
                    out_coordinates: []
                },
                view_dict: {
                    text: lines[1] || '',
                    resource_id: '',
                    class: '',
                    bounds: [[0, 0], [100, 100]]
                }
            });
        });
    });
}

// メイン処理
async function main() {
    const { selector, view_dict } = await parseInput();
    const result = match(selector, view_dict);
    console.log(result ? 'true' : 'false');
}

main();
