    }

    // IPアドレス判定（IPv4）
    const ipv4Pattern = /^(\d{1,3}\.){3}\d{1,3}$/;
    if (ipv4Pattern.test(hostname)) {
        const parts = hostname.split('.').map(Number);
        if (parts.every(p => p >= 0 && p <= 255)) {
            return 'high';
        }
    }

    // IPv6判定
    if (hostname.includes(':')) {
        return 'high';
    }

    // トラスト済みCDN・Microsoft・W3C
    const trustedDomains = [
        'microsoft.com', 'w3.org', 'cloudflare.com', 'akamai.com',
        'fastly.com', 'cdn.jsdelivr.net', 'unpkg.com', 'googleapis.com',
        'gstatic.com', 'amazonaws.com', 'azure.com', 'azureedge.net'
    ];
    for (const domain of trustedDomains) {
        if (hostname === domain || hostname.endsWith('.' + domain)) {
            return 'benign';
        }
    }

    // 既知の良好なベンダー
    const knownVendors = [
        'github.com', 'github.io', 'npmjs.com', 'nodejs.org',
        'python.org', 'docker.com', 'kubernetes.io', 'reactjs.org',
        'vuejs.org', 'angular.io', 'typescriptlang.org', 'stackoverflow.com'
    ];
    for (const domain of knownVendors) {
        if (hostname === domain || hostname.endsWith('.' + domain)) {
            return 'low';
        }
    }

    // タイポスクワッティングパターン（一般的なドメインの類似）
    const commonDomains = ['google', 'facebook', 'amazon', 'apple', 'netflix', 'twitter', 'instagram', 'linkedin'];
    for (const base of commonDomains) {
        if (hostname.startsWith(base) && hostname !== base + '.com') {
            // 完全一致でないが、baseで始まる場合は疑わしい
            if (hostname.length > base.length + 4) { // 例: gooogle.com
                return 'high';
            }
        }
    }

    // 動的ドメイン（数字やハイフンが多い）
    const dynamicPattern = /^[a-z0-9-]+(\.[a-z0-9-]+)+$/;
    if (dynamicPattern.test(hostname)) {
        const labels = hostname.split('.');
        const totalLength = hostname.replace(/\./g, '').length;
        const digitCount = (hostname.match(/\d/g) || []).length;
        const hyphenCount = (hostname.match(/-/g) || []).length;
        if (digitCount > 3 || hyphenCount > 2 || totalLength > 30) {
            return 'high';
        }
    }

    // 未知のドメイン
    return 'medium';
}

