        int n = Integer.parseInt(br.readLine().trim());
        int axis = Integer.parseInt(br.readLine().trim());
        String xvals = br.readLine().trim();

        // ダウンサンプリング実行
        double[] result = downsample(data, n, axis);

        // 出力
        System.out.println(result.length);
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < result.length; i++) {
            if (i > 0) sb.append(" ");
            sb.append(formatDouble(result[i]));
        }
        System.out.println(sb.toString());
    }

    static String formatDouble(double d) {
        if (d == Math.floor(d) && !Double.isInfinite(d)) {
            return String.valueOf((long)d);
        }
        return String.valueOf(d);
    }

    static double[] downsample(double[] data, int n, int axis) {
        if (n <= 1) return data;
        int nPts = data.length / n;
        double[] result = new double[nPts];
        for (int i = 0; i < nPts; i++) {
            double sum = 0;
            for (int j = 0; j < n; j++) {
                sum += data[i * n + j];
            }
            result[i] = sum / n;
        }
        return result;
    }
}
