// テンプレートの非リスト要素数を数える
int countLeaves(const NodePtr& node) {
    if (!node->isList) return 1;
    int total = 0;
    for (auto& child : get<vector<NodePtr>>(node->data)) {
        total += countLeaves(child);
    }
    return total;
}

// unflatten の実装
NodePtr unflatten(const vector<NodePtr>& obj, int& idx, const NodePtr& templateNode) {
    if (!templateNode->isList) {
        // 葉: obj[idx] を返す
        NodePtr result = obj[idx];
        idx++;
        return result;
    }
    // リスト/タプル
    vector<NodePtr> children = get<vector<NodePtr>>(templateNode->data);
    vector<NodePtr> resultChildren;
    for (auto& child : children) {
        int leafCount = countLeaves(child);
        // 子の葉の数だけ obj から取る
        vector<NodePtr> subObj;
        for (int i = 0; i < leafCount; i++) {
            subObj.push_back(obj[idx + i]);
        }
        idx += leafCount;
        int subIdx = 0;
        resultChildren.push_back(unflatten(subObj, subIdx, child));
    }
    NodePtr result = make_shared<Node>();
    result->isList = true;
    result->data = resultChildren;
    return result;
}

