```cpp
#include <iostream>
#include <vector>
#include <string>
#include <sstream>
#include <algorithm>

using namespace std;

// ボリュームを表す構造体（3次元配列）
struct Volume {
    vector<vector<vector<int>>> data;
    int dim_x, dim_y, dim_z;
};

// 入力パース用
vector<int> parse_int_list(const string& s) {
    vector<int> result;
    stringstream ss(s);
    int x;
    while (ss >> x) result.push_back(x);
    return result;
}

// ボリュームの転置
Volume transpose_volume(const Volume& vol, const string& direction) {
    Volume result;
    if (direction == "axial") {
        // axial: 軸の順序を (z, y, x) から (x, y, z) に変更
        result.dim_x = vol.dim_z;
        result.dim_y = vol.dim_y;
        result.dim_z = vol.dim_x;
        result.data.assign(result.dim_x, vector<vector<int>>(result.dim_y, vector<int>(result.dim_z)));
        for (int x = 0; x < vol.dim_x; x++)
            for (int y = 0; y < vol.dim_y; y++)
                for (int z = 0; z < vol.dim_z; z++)
                    result.data[z][y][x] = vol.data[x][y][z];
    } else if (direction == "sagittal") {
        // sagittal: 軸の順序を (x, y, z) から (y, x, z) に変更
        result.dim_x = vol.dim_y;
        result.dim_y = vol.dim_x;
        result.dim_z = vol.dim_z;
        result.data.assign(result.dim_x, vector<vector<int>>(result.dim_y, vector<int>(result.dim_z)));
        for (int x = 0; x < vol.dim_x; x++)
            for (int y = 0; y < vol.dim_y; y++)
                for (int z = 0; z < vol.dim_z; z++)
                    result.data[y][x][z] = vol.data[x][y][z];
    } else { // coronal
        // coronal: 軸の順序を (x, y, z) から (x, z, y) に変更
        result.dim_x = vol.dim_x;
        result.dim_y = vol.dim_z;
        result.dim_z = vol.dim_y;
        result.data.assign(result.dim_x, vector<vector<int>>(result.dim_y, vector<int>(result.dim_z)));
        for (int x = 0; x < vol.dim_x; x++)
            for (int y = 0; y < vol.dim_y; y++)
                for (int z = 0; z < vol.dim_z; z++)
                    result.data[x][z][y] = vol.data[x][y][z];
    }
    return result;
}

int main() {
    // 入力: volumes のリスト
    string line;
    getline(cin, line);
    int num_volumes = stoi(line);

    vector<Volume> volumes;
    for (int i = 0; i < num_volumes; i++) {
        // 各ボリュームの次元情報（3つの整数）
        getline(cin, line);
        vector<int> dims = parse_int_list(line);
        Volume vol;
        vol.dim_x = dims[0];
        vol.dim_y = dims[1];
        vol.dim_z = dims[2];
        vol.data.assign(vol.dim_x, vector<vector<int>>(vol.dim_y, vector<int>(vol.dim_z)));
        // データ読み込み
        for (int x = 0; x < vol.dim_x; x++) {
            for (int y = 0; y < vol.dim_y; y++) {
                getline(cin, line);
                vector<int> vals = parse_int_list(line);
                for (int z = 0; z < vol.dim_z; z++) {
                    vol.data[x][y][z] = vals[z];
                }
            }
        }
        volumes.push_back(vol);
    }

    // 入力: slice_direction
    getline(cin, line);
    string direction = line;

    // 転置処理
    vector<Volume> tr_volumes;
    for (const auto& vol : volumes) {
        tr_volumes.push_back(transpose_volume(vol, direction));
    }

    // 出力
    cout << tr_volumes.size() << endl;
    for (const auto& vol : tr_volumes) {
        cout << vol.dim_x << " " << vol.dim_y << " " << vol.dim_z << endl;
        for (int x = 0; x < vol.dim_x; x++) {
            for (int y = 0; y < vol.dim_y; y++) {
                for (int z = 0; z < vol.dim_z; z++) {
                    cout << vol.data[x][y][z];
                    if (z < vol.dim_z - 1) cout << " ";
                }
                cout << endl;
            }
        }
    }

    return 0;
}
