```cpp
#include <iostream>
#include <string>
#include <vector>
#include <sstream>
#include <unordered_map>
#include <memory>

using namespace std;

// 簡易的なJSON風パーサー（必要な部分のみ）
struct JsonValue {
    enum Type { NONE, BOOL, INT, STRING, LIST, DICT } type = NONE;
    bool bool_val = false;
    long long int_val = 0;
    string str_val;
    vector<JsonValue> list;
    unordered_map<string, JsonValue> dict;
};

JsonValue parse_value(const string& s, size_t& pos);

void skip_ws(const string& s, size_t& pos) {
    while (pos < s.size() && isspace(s[pos])) pos++;
}

JsonValue parse_value(const string& s, size_t& pos) {
    skip_ws(s, pos);
    if (pos >= s.size()) return JsonValue();
    char c = s[pos];
    if (c == '[') {
        pos++;
        JsonValue v; v.type = JsonValue::LIST;
        skip_ws(s, pos);
        if (pos < s.size() && s[pos] == ']') { pos++; return v; }
        while (true) {
            v.list.push_back(parse_value(s, pos));
            skip_ws(s, pos);
            if (pos < s.size() && s[pos] == ',') { pos++; continue; }
            if (pos < s.size() && s[pos] == ']') { pos++; break; }
            break;
        }
        return v;
    } else if (c == '{') {
        pos++;
        JsonValue v; v.type = JsonValue::DICT;
        skip_ws(s, pos);
        if (pos < s.size() && s[pos] == '}') { pos++; return v; }
        while (true) {
            skip_ws(s, pos);
            string key;
            if (pos < s.size() && s[pos] == '\'') {
                pos++;
                while (pos < s.size() && s[pos] != '\'') { key += s[pos]; pos++; }
                if (pos < s.size()) pos++;
            } else {
                while (pos < s.size() && s[pos] != ':' && s[pos] != ',' && s[pos] != '}') { key += s[pos]; pos++; }
            }
            skip_ws(s, pos);
            if (pos < s.size() && s[pos] == ':') pos++;
            v.dict[key] = parse_value(s, pos);
            skip_ws(s, pos);
            if (pos < s.size() && s[pos] == ',') { pos++; continue; }
            if (pos < s.size() && s[pos] == '}') { pos++; break; }
            break;
        }
        return v;
    } else if (c == 't') {
        pos += 4;
        JsonValue v; v.type = JsonValue::BOOL; v.bool_val = true; return v;
    } else if (c == 'f') {
        pos += 5;
        JsonValue v; v.type = JsonValue::BOOL; v.bool_val = false; return v;
    } else if (c == 'N') {
        pos += 4;
        return JsonValue(); // None
    } else if (c == '\'') {
        pos++;
        string val;
        while (pos < s.size() && s[pos] != '\'') { val += s[pos]; pos++; }
        if (pos < s.size()) pos++;
        JsonValue v; v.type = JsonValue::STRING; v.str_val = val; return v;
    } else if (isdigit(c) || c == '-') {
        string num;
        while (pos < s.size() && (isdigit(s[pos]) || s[pos] == '-' || s[pos] == '.')) { num += s[pos]; pos++; }
        JsonValue v; v.type = JsonValue::INT; v.int_val = stoll(num); return v;
    }
    return JsonValue();
}

// 再帰的にチェックする関数
bool has_skip_no_cumulative(const JsonValue& v) {
    if (v.type == JsonValue::DICT) {
        bool has_skip = v.dict.count("skip") > 0;
        bool has_cumulative = v.dict.count("cumulative") > 0;
        if (has_skip && !has_cumulative) return true;
        // サブスライスを再帰的に探索
        for (const auto& kv : v.dict) {
            if (has_skip_no_cumulative(kv.second)) return true;
        }
    } else if (v.type == JsonValue::LIST) {
        for (const auto& item : v.list) {
            if (has_skip_no_cumulative(item)) return true;
        }
    }
    return false;
}

