using System;
using System.Text;

class Program
{
    static string ReformatRemoveUnresolvedReferences(string text)
    {
        StringBuilder newText = new StringBuilder();
        while (text.Length > 1)
        {
            int idx = text.IndexOf('[');
            if (idx >= 0)
            {
                newText.Append(text.Substring(0, idx));
                int idx1 = idx + 1;
                while (idx1 < text.Length && char.IsDigit(text[idx1]))
                {
                    idx1++;
                }
                if (idx1 + 1 < text.Length)
                {
                    if (text.Substring(idx1, 2) != "]_")
                    {
                        newText.Append(text.Substring(idx, idx1 + 2 - idx));
                    }
                    if (idx1 + 2 < text.Length)
                    {
                        text = text.Substring(idx1 + 2);
                    }
                    else
                    {
                        text = "";
                    }
                }
                else
                {
                    newText.Append(text.Substring(idx));
                    text = "";
                }
            }
            else
            {
                newText.Append(text);
                text = "";
            }
        }
        return newText.ToString();
    }

    static void Main()
    {
        string input = Console.ReadLine();
        Console.WriteLine(ReformatRemoveUnresolvedReferences(input));
    }
}
