```csharp
using System;
using System.Collections.Generic;
using System.Linq;

class Program
{
    static void Main()
    {
        // 入力読み取り
        int n = int.Parse(Console.ReadLine());
        List<string> values = new List<string>();
        if (n > 0)
        {
            string line = Console.ReadLine();
            values = line.Split(' ').ToList();
        }
        int maxSamples = int.Parse(Console.ReadLine());

        // 関数呼び出し
        List<float> result = EvenlySample(values, maxSamples);

        // 出力
        Console.WriteLine(result.Count);
        if (result.Count > 0)
        {
            Console.WriteLine(string.Join(" ", result.Select(x => x.ToString("0.0"))));
        }
    }

    static List<float> EvenlySample(List<string> values, int maxSamples)
    {
        List<float> floats = values.Select(x => float.Parse(x)).ToList();
        if (floats.Count <= maxSamples)
        {
            return floats;
        }

        List<float> sampled = new List<float>();
        // 等間隔インデックス計算: 開始0、終了count-1、サンプル数maxSamples
        for (int i = 0; i < maxSamples; i++)
        {
            int index = (int)Math.Round((double)i * (floats.Count - 1) / (maxSamples - 1));
            sampled.Add(floats[index]);
        }
        return sampled;
    }
}
