```csharp
using System;
using System.Collections.Generic;
using System.Linq;

class Program
{
    static void Main()
    {
        // 入力読み込み
        int size_m = int.Parse(Console.ReadLine());
        int[] output_indices = new int[size_m];
        string[] tokens = Console.ReadLine().Split(' ');
        for (int i = 0; i < size_m; i++)
        {
            output_indices[i] = int.Parse(tokens[i]);
        }
        int chunk_size = int.Parse(Console.ReadLine());

        // 関数呼び出し
        var result = ComputeSendRouting(output_indices, chunk_size);

        // 出力
        Console.WriteLine(result.send_dest_chips.Length);
        Console.WriteLine(string.Join(" ", result.send_dest_chips));
        Console.WriteLine(result.send_local_rows.Length);
        Console.WriteLine(string.Join(" ", result.send_local_rows));
    }

    static (int[] send_dest_chips, int[] send_local_rows) ComputeSendRouting(int[] output_indices, int chunk_size)
    {
        // 妥当性チェック
        if (chunk_size <= 0)
            throw new ArgumentException("chunk_size must be positive");

        int size_m = output_indices.Length;
        if (size_m == 0)
            throw new ArgumentException("output_indices cannot be empty");

        // 各要素が非負であること
        if (output_indices.Any(x => x < 0))
            throw new ArgumentException("output_indices must be non-negative");

        // 各要素がchunk_size * チップ数未満であること（チップ数はsize_m / chunk_size）
        if (size_m % chunk_size != 0)
            throw new ArgumentException("size_m must be divisible by chunk_size");

        int ep_size = size_m / chunk_size;
        foreach (int idx in output_indices)
        {
            if (idx >= chunk_size * ep_size)
                throw new ArgumentException("output_indices value out of range");
        }

        // 計算
        int[] send_dest_chips = new int[size_m];
        int[] send_local_rows = new int[size_m];
        for (int i = 0; i < size_m; i++)
        {
            send_dest_chips[i] = output_indices[i] / chunk_size;
            send_local_rows[i] = output_indices[i] % chunk_size;
        }

        return (send_dest_chips, send_local_rows);
    }
}
