    static bool IsTorchOOM(Exception exc)
    {
        if (exc == null) return false;

        // 型名で判定 (torch.cuda.OutOfMemoryError は RuntimeError のサブクラス)
        string typeName = exc.GetType().FullName ?? "";
        if (typeName.Contains("OutOfMemoryError") && typeName.Contains("cuda"))
            return true;

        // メッセージで判定 (CUDA と MPS の両方)
        string message = exc.Message ?? "";
        if (message.Contains("CUDA out of memory") || 
            message.Contains("MPS backend out of memory"))
            return true;

        return false;
    }

