                exc = new Exception("CUDA out of memory");
                break;
            case "RuntimeError":
                exc = new Exception("CUDA out of memory");
                break;
            case "MPS":
                exc = new Exception("MPS backend out of memory");
                break;
            default:
                exc = new Exception("some other error");
                break;
        }

        bool result = IsTorchOOM(exc);
