// Timeseries は簡易的な時系列オブジェクトを表す
type Timeseries struct {
	data []float64
}

// NewTimeseries は新しいTimeseriesを作成する
func NewTimeseries(data []float64) *Timeseries {
	return &Timeseries{data: data}
}

// _checkNewObject はプライベート関数。inplaceがtrueならselfを返し、falseなら新しいオブジェクトを返す
func (ts *Timeseries) _checkNewObject(inplace bool) *Timeseries {
	if inplace {
		return ts
	}
	// 新しいオブジェクトを作成（データはコピー）
	newData := make([]float64, len(ts.data))
	copy(newData, ts.data)
	return NewTimeseries(newData)
}

