実装方針として、入力文字列を「度:分:秒」形式または10進数の度に応じて変換し、backパラメータが1.0なら10進数から度分秒へ、0.0なら度分秒から10進数へ変換する関数を実装します。

```go
package main

import (
	"bufio"
	"fmt"
	"os"
	"strconv"
	"strings"
)

func convertDeg(input string, back float64) string {
	if back == 1.0 {
		// 10進数の度を度分秒に変換
		deg, err := strconv.ParseFloat(input, 64)
		if err != nil {
			return ""
		}
		// 符号を保持
		sign := 1.0
		if deg < 0 {
			sign = -1.0
			deg = -deg
		}
		d := int(deg)
		frac := deg - float64(d)
		mFloat := frac * 60
		m := int(mFloat)
		sFloat := (mFloat - float64(m)) * 60
		// 秒を小数点以下6桁で丸める
		s := fmt.Sprintf("%.6f", sFloat)
		// 余分な0を削除
		s = strings.TrimRight(s, "0")
		s = strings.TrimRight(s, ".")
		return fmt.Sprintf("%d:%d:%s", int(sign)*d, m, s)
	} else {
		// 度分秒を10進数に変換
		parts := strings.Split(input, ":")
		if len(parts) != 3 {
			return ""
		}
		d, err1 := strconv.ParseFloat(parts[0], 64)
		m, err2 := strconv.ParseFloat(parts[1], 64)
		s, err3 := strconv.ParseFloat(parts[2], 64)
		if err1 != nil || err2 != nil || err3 != nil {
			return ""
		}
		// 符号を考慮
		sign := 1.0
		if d < 0 {
			sign = -1.0
			d = -d
		}
		result := sign * (d + m/60 + s/3600)
		// 小数点以下6桁で出力
		return fmt.Sprintf("%.6f", result)
	}
}

func main() {
	scanner := bufio.NewScanner(os.Stdin)
	var lines []string
	for scanner.Scan() {
		lines = append(lines, scanner.Text())
	}
	if len(lines) < 2 {
		return
	}
	input := lines[0]
	back, err := strconv.ParseFloat(lines[1], 64)
	if err != nil {
		return
	}
	fmt.Println(convertDeg(input, back))
}
```

実装方針: 入力された整数を2進数に変換し、LSBから順にビットのリストを作成します。オプションのビット数指定がある場合は、指定された長さになるよう上位に0を追加します。

```go
package main

import (
	"bufio"
	"fmt"
	"os"
	"strconv"
	"strings"
)

func intToBits(n int, bitLen ...int) []int {
	// デフォルトのビット長は、nを表現するのに必要な最小ビット数
	bits := []int{}
	if n == 0 {
		bits = append(bits, 0)
	} else {
		for n > 0 {
			bits = append(bits, n%2)
			n /= 2
		}
	}

	// 指定されたビット長がある場合、必要に応じて0を追加
	if len(bitLen) > 0 {
		required := bitLen[0]
		for len(bits) < required {
			bits = append(bits, 0)
		}
	}
	return bits
}

func main() {
	scanner := bufio.NewScanner(os.Stdin)
	scanner.Scan()
	n, _ := strconv.Atoi(scanner.Text())

	// オプションのビット長を読み取る
	bitLen := []int{}
	if scanner.Scan() {
		line := scanner.Text()
		if line != "" {
			bitLenVal, _ := strconv.Atoi(line)
			bitLen = append(bitLen, bitLenVal)
		}
	}

	result := intToBits(n, bitLen...)

	// 出力形式: 要素数、要素を空白区切り
	fmt.Println(len(result))
	fmt.Println(strings.Trim(strings.Join(strings.Fields(fmt.Sprint(result)), " "), "[]"))
}
