```rust
use std::collections::HashMap;
use std::io::{self, BufRead};

fn parse_attributes(text: &str) -> HashMap<String, String> {
    let mut attributes = HashMap::new();
    let text = text.trim();

    // セパレータの検出（= または スペース）
    let sep = text.chars().find(|c| *c == '=' || *c == ' ').unwrap_or_else(|| {
        eprintln!("Your GFF/GTF does not seem to be correct ({}). Expected a = or space as separator", text);
        std::process::exit(1);
    });

    // URLデコード（%XX形式の置換）
    let mut decoded = String::new();
    let bytes = text.as_bytes();
    let mut i = 0;
    while i < bytes.len() {
        if bytes[i] == b'%' && i + 2 < bytes.len() {
            if let (Some(hi), Some(lo)) = (hex_val(bytes[i+1]), hex_val(bytes[i+2])) {
                decoded.push((hi * 16 + lo) as char);
                i += 3;
                continue;
            }
        }
        decoded.push(bytes[i] as char);
        i += 1;
    }

    // 正規表現パターン: (\S+?)[= ](".*?"|[^;]*)(?:;|$)
    // 手動パースで実装
    let chars: Vec<char> = decoded.chars().collect();
    let mut pos = 0;
    let n = chars.len();

    while pos < n {
        // キーを読み取る（空白や=まで）
        let key_start = pos;
        while pos < n && chars[pos] != '=' && chars[pos] != ' ' && chars[pos] != ';' {
            pos += 1;
        }
        if pos >= n || chars[pos] == ';' {
            break;
        }
        let key: String = chars[key_start..pos].iter().collect();

        // セパレータをスキップ
        if pos < n && (chars[pos] == '=' || chars[pos] == ' ') {
            pos += 1;
        }

        // 値を読み取る
        let mut value = String::new();
        if pos < n && chars[pos] == '"' {
            // 引用符で囲まれた値
            pos += 1;
            while pos < n && chars[pos] != '"' {
                value.push(chars[pos]);
                pos += 1;
            }
            if pos < n {
                pos += 1; // 閉じ引用符をスキップ
            }
        } else {
            // 引用符なしの値（セミコロンまで）
            while pos < n && chars[pos] != ';' {
                value.push(chars[pos]);
                pos += 1;
            }
        }

        attributes.insert(key, value);

        // セミコロンをスキップ
        if pos < n && chars[pos] == ';' {
            pos += 1;
        }
    }

    attributes
}

fn hex_val(c: u8) -> Option<u8> {
    match c {
        b'0'..=b'9' => Some(c - b'0'),
        b'a'..=b'f' => Some(c - b'a' + 10),
        b'A'..=b'F' => Some(c - b'A' + 10),
        _ => None,
    }
}

fn main() {
    let stdin = io::stdin();
    let mut lines = stdin.lock().lines();

    // 入力形式: 最初の行は引数の数（ここでは1）
    let _arg_count: usize = lines.next().unwrap().unwrap().trim().parse().unwrap();

    // 引数（text）を読み取る
    let text = lines.next().unwrap().unwrap();

    let result = parse_attributes(&text);

    // 出力をPythonの辞書形式で
    let mut output = String::from("{");
    let mut first = true;
    for (k, v) in &result {
        if !first {
            output.push_str(", ");
        }
        output.push('\'');
        output.push_str(k);
        output.push_str("': '");
        output.push_str(v);
        output.push('\'');
        first = false;
    }
    output.push('}');
    println!("{}", output);
}
