```typescript
type Callable<T> = (value: any) => T;

class TypeConversionDict {
    private data: Record<string, any>;

    constructor(data: Record<string, any>) {
        this.data = data;
    }

    get(key: string, defaultVal: any = null, type?: Callable<any>): any {
        const value = this.data[key];

        if (value !== undefined) {
            if (type) {
                try {
                    return type(value);
                } catch (error) {
                    if (error instanceof TypeError || error instanceof RangeError) {
                        return defaultVal;
                    }
                    throw error;
                }
            }
            return value;
        }
        return defaultVal;
    }
}

