```typescript
function mapSingleLabel(labelName: string): string {
    const entityMappings: Record<string, [string, string]> = {
        'nam_liv': ['B-PER', 'I-PER'],
        'nam_loc': ['B-LOC', 'I-LOC'],
        'nam_org': ['B-ORG', 'I-ORG']
    };

    if (labelName === 'O') {
        return 'O';
    }

    const prefix = labelName.startsWith('B-') ? 'B-' : labelName.startsWith('I-') ? 'I-' : '';
    const keyword = Object.keys(entityMappings).find(key => labelName.includes(key));

    if (keyword) {
        return labelName.startsWith('B-') ? entityMappings[keyword][0] : entityMappings[keyword][1];
    }

    if (prefix === 'B-') {
        return 'B-MISC';
    } else if (prefix === 'I-') {
        return 'I-MISC';
    }

    return 'O';
}

