```typescript
function categorizeURL(input: string): string {
    const benignDomains = ['microsoft.com', 'w3.org', 'cdn.jsdelivr.net', 'cdnjs.cloudflare.com'];
    const lowRiskDomains = ['github.com', 'npmjs.com'];
    const ipPattern = /^(25[0-5]|2[0-4][0-9]|[01]?[0-9][0-9]?)\.(25[0-5]|2[0-4][0-9]|[01]?[0-9][0-9]?)\.(25[0-5]|2[0-4][0-9]|[01]?[0-9][0-9]?)\.(25[0-5]|2[0-4][0-9]|[01]?[0-9][0-9]?)$/;
    const typoPattern = /xn--/;
    const dynamicDomainPattern = /-[0-9a-f]{10,}$/;

    function extractDomain(url: string): string {
        const urlObj = new URL(url);
        return urlObj.hostname.toLowerCase();
    }

    const domain = extractDomain(input);

    if (benignDomains.includes(domain)) {
        return 'benign';
    }

    if (lowRiskDomains.includes(domain)) {
        return 'low';
    }

    if (ipPattern.test(domain)) {
        return 'high';
    }

    if (typoPattern.test(domain) || dynamicDomainPattern.test(domain)) {
        return 'high';
    }

    return 'medium';
}

// 標準入力を処理し、結果を出力
const input = 'https://www.microsoft.com/';
console.log(categorizeURL(input));
