import java.util.Scanner;

class ParaxialModel {
    // ParaxialModelのプロパティとメソッドを定義
    // この例では、具体的な実装は省略
}

public class LensDecoder {

    public static Object[] decodeLens(Object lensPackage) {
        ParaxialModel paraxModel;
        int bgn, end;

        if (lensPackage instanceof Tuple) {
            Tuple lensPackageTuple = (Tuple) lensPackage;
            paraxModel = (ParaxialModel) lensPackageTuple.getFirst();
            Tuple indices = (Tuple) lensPackageTuple.getSecond();
            bgn = (Integer) indices.getFirst();
            end = (Integer) indices.getSecond();
        } else {
            paraxModel = (ParaxialModel) lensPackage;
            bgn = 1;
            end = -1;
        }

        return new Object[]{paraxModel, bgn, end};
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        // 入力を読み取る
        Object lensPackage = readInput(scanner);

        // decodeLensを呼び出して結果を取得
        Object[] result = decodeLens(lensPackage);

        // 結果を出力
        System.out.println(result[1] + " " + result[2]);
    }

    private static Object readInput(Scanner scanner) {
        int n = scanner.nextInt();
        scanner.nextLine(); // 改行を消費

        if (n == 1) {
            // ParaxialModelの場合
            return new ParaxialModel();
        } else {
            // Tupleの場合
            ParaxialModel paraxModel = new ParaxialModel();
            int bgn = scanner.nextInt();
            int end = scanner.nextInt();
            scanner.nextLine(); // 改行を消費

            Tuple indices = new Tuple(bgn, end);
            return new Tuple(paraxModel, indices);
        }
    }
}

class Tuple {
    private final Object first;
    private final Object second;

    public Tuple(Object first, Object second) {
        this.first = first;
        this.second = second;
    }

    public Object getFirst() {
        return first;
    }

    public Object getSecond() {
        return second;
    }
}
