using NestedType = std::variant<int, std::string, std::vector<std::shared_ptr<NestedType>>, std::tuple<std::shared_ptr<NestedType>, std::shared_ptr<NestedType>>>;

// 文字列を解析してバリアントに変換
NestedType parse(const std::string& str) {
    if (str == "None") return nullptr;
    if (str == "true") return true;
    if (str == "false") return false;
    if (str.front() == '[') {
        std::vector<std::shared_ptr<NestedType>> vec;
        std::string inner = str.substr(1, str.size() - 2);
        std::istringstream iss(inner);
        std::string item;
        while (std::getline(iss, item, ' ')) {
            vec.push_back(std::make_shared<NestedType>(parse(item)));
        }
        return vec;
    }
    if (str.front() == '(') {
        std::string inner = str.substr(1, str.size() - 2);
        std::istringstream iss(inner);
        std::string item1, item2;
        std::getline(iss, item1, ',');
        std::getline(iss, item2);
        return std::make_tuple(std::make_shared<NestedType>(parse(item1)), std::make_shared<NestedType>(parse(item2)));
    }
    if (str.front() == '{') {
        // 辞書の場合は、ここで処理する必要がありますが、例ではシンプルに扱います
        return str;
    }
    return str; // 数値または文字列
}

// テンプレートの長さを計算
int unflat_len(const NestedType& template_) {
    if (std::holds_alternative<int>(template_) || std::holds_alternative<std::string>(template_)) {
        return 1;
    }
    if (std::holds_alternative<std::vector<std::shared_ptr<NestedType>>>(template_)) {
        int sum = 0;
        for (const auto& elem : std::get<std::vector<std::shared_ptr<NestedType>>>(template_)) {
            sum += unflat_len(*elem);
        }
        return sum;
    }
    if (std::holds_alternative<std::tuple<std::shared_ptr<NestedType>, std::shared_ptr<NestedType>>>(template_)) {
        return unflat_len(*std::get<0>(std::get<std::tuple<std::shared_ptr<NestedType>, std::shared_ptr<NestedType>>>(template_))) +
               unflat_len(*std::get<1>(std::get<std::tuple<std::shared_ptr<NestedType>, std::shared_ptr<NestedType>>>(template_)));
    }
    return 0; // これは基本的には起こらないはず
}

// リストまたはタプルのオブジェクトを再構成
NestedType unflatten(const std::vector<NestedType>& obj, const NestedType& template_) {
    if (std::holds_alternative<int>(template_) || std::holds_alternative<std::string>(template_)) {
        return obj.front();
    }
    if (std::holds_alternative<std::vector<std::shared_ptr<NestedType>>>(template_)) {
        std::vector<std::shared_ptr<NestedType>> vec;
        auto& template_vec = std::get<std::vector<std::shared_ptr<NestedType>>>(template_);
        std::vector<int> lengths(template_vec.size());
        for (size_t i = 0; i < template_vec.size(); ++i) {
            lengths[i] = unflat_len(*template_vec[i]);
        }
        int start = 0;
        for (size_t i = 0; i < template_vec.size(); ++i) {
            int end = start + lengths[i];
            std::vector<NestedType> sub_obj(obj.begin() + start, obj.begin() + end);
            vec.push_back(std::make_shared<NestedType>(unflatten(sub_obj, *template_vec[i])));
            start = end;
        }
        return vec;
    }
    if (std::holds_alternative<std::tuple<std::shared_ptr<NestedType>, std::shared_ptr<NestedType>>>(template_)) {
        auto& template_tuple = std::get<std::tuple<std::shared_ptr<NestedType>, std::shared_ptr<NestedType>>>(template_);
        int len1 = unflat_len(*std::get<0>(template_tuple));
        std::vector<NestedType> sub_obj1(obj.begin(), obj.begin() + len1);
        std::vector<NestedType> sub_obj2(obj.begin() + len1, obj.end());
        return std::make_tuple(std::make_shared<NestedType>(unflatten(sub_obj1, *std::get<0>(template_tuple))),
                               std::make_shared<NestedType>(unflatten(sub_obj2, *std::get<1>(template_tuple))));
    }
    return nullptr; // これは基本的には起こらないはず
}

