#include <iostream>
#include <vector>
#include <string>
#include <sstream>

using namespace std;

vector<vector<vector<vector<int>>>> readVolumes(int numVolumes, int dimX, int dimY, int dimZ) {
    vector<vector<vector<vector<int>>>> volumes(numVolumes, vector<vector<int>>(dimX, vector<int>(dimY, vector<int>(dimZ)));
    for (int v = 0; v < numVolumes; ++v) {
        for (int x = 0; x < dimX; ++x) {
            for (int y = 0; y < dimY; ++y) {
                for (int z = 0; z < dimZ; ++z) {
                    cin >> volumes[v][x][y][z];
                }
            }
        }
    }
    return volumes;
}

vector<vector<vector<vector<int>>>> transposeVolumes(const vector<vector<vector<vector<int>>>>& volumes, const string& sliceDirection, int dimX, int dimY, int dimZ) {
    vector<vector<vector<vector<int>>>> transposedVolumes = volumes;
    if (sliceDirection == "axial") {
        for (int v = 0; v < volumes.size(); ++v) {
            for (int x = 0; x < dimX; ++x) {
                for (int y = 0; y < dimY; ++y) {
                    for (int z = 0; z < dimZ; ++z) {
                        transposedVolumes[v][x][y][z] = volumes[v][x][z][y];
                    }
                }
            }
        }
    } else if (sliceDirection == "sagittal") {
        for (int v = 0; v < volumes.size(); ++v) {
            for (int x = 0; x < dimX; ++x) {
                for (int y = 0; y < dimY; ++y) {
                    for (int z = 0; z < dimZ; ++z) {
                        transposedVolumes[v][x][y][z] = volumes[v][z][x][y];
                    }
                }
            }
        }
    } else if (sliceDirection == "coronal") {
        for (int v = 0; v < volumes.size(); ++v) {
            for (int x = 0; x < dimX; ++x) {
                for (int y = 0; y < dimY; ++y) {
                    for (int z = 0; z < dimZ; ++z) {
                        transposedVolumes[v][x][y][z] = volumes[v][y][z][x];
                    }
                }
            }
        }
    }
    return transposedVolumes;
}

void printVolumes(const vector<vector<vector<vector<int>>>>& volumes) {
    int numVolumes = volumes.size();
    int dimX = volumes[0].size();
    int dimY = volumes[0][0].size();
    int dimZ = volumes[0][0][0].size();
    cout << numVolumes << endl;
    cout << dimX << " " << dimY << " " << dimZ << endl;
    for (const auto& volume : volumes) {
        for (const auto& slice : volume) {
            for (const auto& row : slice) {
                for (const auto& val : row) {
                    cout << val << " ";
                }
                cout << endl;
            }
            cout << endl;
        }
        cout << endl;
    }
}

int main() {
    int numVolumes;
    int dimX, dimY, dimZ;
    string sliceDirection;

    // Read number of volumes
    cin >> numVolumes;
    cin.ignore();

    // Read each volume dimensions and data
    cin >> dimX >> dimY >> dimZ;
    cin.ignore();
    vector<vector<vector<vector<int>>>> volumes = readVolumes(numVolumes, dimX, dimY, dimZ);

    // Read slice direction
    cin >> sliceDirection;

    // Transpose volumes
    vector<vector<vector<vector<int>>>> transposedVolumes = transposeVolumes(volumes, sliceDirection, dimX, dimY, dimZ);

    // Print transposed volumes
    printVolumes(transposedVolumes);

    return 0;
}
