```csharp
using System;

class Program
{
    static bool IsTorchOutOfMemoryError(Exception exc)
    {
        if (exc is RuntimeError)
        {
            if (exc.Message.Contains("MPS backend out of memory"))
            {
                return true;
            }
            if (exc.GetType().FullName == "torch.cuda.OutOfMemoryError")
            {
                return true;
            }
        }
        return false;
    }

    static void Main()
    {
        // テストケース
        Exception exc1 = new RuntimeError("MPS backend out of memory");
        Console.WriteLine(IsTorchOutOfMemoryError(exc1)); // true

