        Console.WriteLine(IsTorchOutOfMemoryError(exc2)); // false

        Exception exc3 = new RuntimeError("torch.cuda.OutOfMemoryError");
        Console.WriteLine(IsTorchOutOfMemoryError(exc3)); // true

        Exception exc4 = new Exception("Generic exception");
        Console.WriteLine(IsTorchOutOfMemoryError(exc4)); // false
    }
}

class RuntimeError : Exception
{
    public RuntimeError(string message) : base(message) { }
}
```

