```rust
use std::collections::HashMap;
use regex::Regex;
use urlencoding::decode;

fn parse_attributes(text: &str) -> HashMap<String, String> {
    let mut attributes = HashMap::new();
    let text = decode(text).unwrap_or_else(|_| text.to_string());

    let mut sep = None;
    for c in text.chars() {
        if c == '=' || c == ' ' {
            sep = Some(c);
            break;
        }
    }

    if sep.is_none() {
        panic!("Your GFF/GTF does not seem to be correct. Expected a = or space as separator");
    }

    let pattern = if *sep == '=' {
        Regex::new(r"(?P<key>\S+?)=(?P<value>\".*?\"|[^;]*)(?:;|$)").unwrap()
    } else {
        Regex::new(r"(?P<key>\S+?)\s+(?P<value>\".*?\"|[^;]*)(?:;|$)").unwrap()
    };

    for cap in pattern.captures_iter(text) {
        let key = cap.name("key").unwrap().as_str().to_string();
        let value = cap.name("value").unwrap().as_str().trim_matches('"').to_string();
        attributes.insert(key, value);
    }

    attributes
}

fn main() {
    let input = "key1=value1;key2=\"value2 with spaces\";key3=value3;key4=\"value4;with;semicolons\"";
    let result = parse_attributes(input);
    for (key, value) in result {
        println!("{}: {}", key, value);
    }
}
```

