use std::collections::HashMap;
use std::iter::FromIterator;

fn _items<I>(iterable: I) -> impl Iterator<Item = (i32, i32)>
where
    I: IntoIterator<Item = (i32, i32)>,
{
    iterable.into_iter()
}

fn main() {
    // テスト例: ジェネレーターを使用
    let gen = (0..5).map(|i| (i as i32, i as i32 * i as i32));
    for (k, v) in _items(gen) {
        assert_eq!(k * k, v);
    }

    // テスト例: 辞書を使用
    let dict: HashMap<i32, i32> = (0..5).map(|i| (i as i32, i as i32 * i as i32)).collect();
    for (k, v) in _items(dict) {
        assert_eq!(k * k, v);
    }

